mapper.select:
SELECT
    fl.ID, fl.NAME, fl.URL, fl.LOGO, fl.DESCRIPTION, fl.LINK_TYPE,
    fl.STATUS, fl.IS_VISIBLE, fl.ALLOW_FOLLOW, fl.CHECK_ENABLED, fl.SORT, fl.CREATE_TIME,
    fls.CLICK_COUNT, fls.DAY_CLICK, fls.WEEK_CLICK, fls.MONTH_CLICK, fls.LAST_CLICK_TIME,
    flh.STATUS AS CHECK_STATUS
FROM friend_link fl
LEFT JOIN friend_link_stat fls ON fls.LINK_ID = fl.ID
LEFT JOIN friend_link_health flh ON flh.LINK_ID = fl.ID



        AND fl.NAME LIKE #{nameBind}



        AND fl.URL LIKE #{urlBind}


        AND fl.LINK_TYPE = #{query.linkType}


        AND fl.STATUS = #{query.status}


        AND fl.IS_VISIBLE = #{query.isVisible}


        AND fl.ALLOW_FOLLOW = #{query.allowFollow}


        AND fl.CHECK_ENABLED = #{query.checkEnabled}


ORDER BY fl.SORT DESC, fl.CREATE_TIME DESC
